def shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    idx = [i for i in range(len(seq))]
    for i in range(len(idx)):
        if i == 0:
            next_idx = idx[i]
        else:
            next_idx = idx[i - (len(idx) - i) % len(idx)]
        seq[i], seq[next_idx] = seq[next_idx], seq[i]
    return seq
