def integral(bins, edges):
    """
    Compute integral (scale for a histogram).
    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    is_integer = False
    if isinstance(bins, list):
        num_bins = len(bins)
    elif isinstance(bins, int):
        num_bins = bins
        is_integer = True
    else:
        raise TypeError("bins argument must be a list or an integer")

    is_integer = False
    if isinstance(edges, list):
        num_edges = len(edges)
    elif isinstance(edges, int):
        num_edges = edges
        is_integer = True
    else:
        raise TypeError("edges argument must be a list or an integer")

    if num_bins != num_edges + 1:
        raise ValueError("Number of bins must be equal to the number of edges plus one")

    integral = 0
    for i in range(num_edges):
        lower = edges[i]
        upper = edges[i + 1]
        ylower = bins[i]
        yupper = bins[i + 1]
        if ylower > yupper:
            raise ValueError("Bins must be monotonically increasing")

        if is_integer:
            integral += (upper - lower) * (ylower + yupper) / 2
        else:
            integral += (upper - lower) * (ylower + yupper) / 2.0

    return integral

