def difference(d1, d2, level=-1):
    def _diff(cur_d1, cur_d2, level=level):
        if not (isinstance(cur_d1, dict) or isinstance(cur_d2, dict)):
            return cur_d1 != cur_d2

        if level == 0:
            return cur_d1 != cur_d2

        d1_diff = set(cur_d1.keys()) - set(cur_d2.keys())
        d2_diff = set(cur_d2.keys()) - set(cur_d1.keys())
        common_keys = set(cur_d1.keys()) & set(cur_d2.keys())

        for key in common_keys:
            if _diff(cur_d1[key], cur_d2[key], level - 1):
                d1_diff.add(key)
                d2_diff.add(key)

        return dict(list(zip(d1_diff, [cur_d1[key] for key in d1_diff])))

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    if not isinstance(d1, dict):
        raise TypeError("'d1' must be a dictionary")
    if not isinstance(d2, dict):
        raise TypeError("'d2' must be a dictionary")
    if not isinstance(level, int):
        raise TypeError("'level' must be an integer")
    if level != -1 and level < 0:
        raise ValueError("'level' must be -1 or a positive integer")

    result = {}
    for k, v in d1.items():
        if k not in d2 or d1[k] != d2[k]:
            if level == 0:
                result[k] = d1[k]
            elif level > 0:
                if isinstance(v, dict):
                    result[k] = difference(v, d2.get(k, {}), level - 1)
                else:
                    result[k] = d1[k]

    return result

