def difference(d1, d2, level=-1):
    d1 = d1.copy()
    if level != 0:
        for key, value in d2.items():
            if key in d1 and d1[key] != value:
                d1.pop(key)
            elif key in d1 and isinstance(d1[key], dict) and isinstance(value, dict):
                d1[key] = difference(d1[key], value, level-1)
            elif key in d1 and any(isinstance(d1[key][k], dict) and isinstance(value[k], dict) for k in value):
                d1[key] = difference(d1[key], value, level-1)
    return d1
