def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    import re
    from collections import namedtuple
    from err import ValidationError

    Pattern = namedtuple("Pattern", ["expression", "message"])

    patterns = {
        "key": Pattern(r"[A-Za-z0-9-_]+$", "Label key should only contain letters, "
                                           "numbers, dashes and underscores."),
        "value": Pattern(r"[A-Za-z0-9-_]+$", "Label value should only contain letters, "
                                           "numbers, dashes and underscores.")
    }

    errors = {}

    for key, value in labels.items():
        if not isinstance(key, str):
            errors[key] = "expected string or bytes-like object"
        else:
            key_match = patterns["key"].expression.match(key)
            if not key_match:
                errors[key] = f"Label key '{key}' does not match the regex {patterns['key'].expression}"
            elif any(char.isupper() for char in key):
                errors[key] = "Label key should only contain lowercase letters."
        if not isinstance(value, str):
            errors[value] = "expected string or bytes-like object"
        elif isinstance(value, (list, tuple)):
            errors[value] = "Label value should not be a list or tuple."
        elif any(char.isupper() for char in key):
            errors[value] = "Label value should only contain lowercase letters."

    if errors:
        raise ValidationError(error_messages=errors)

