    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present.
    """
    for field in observer_schema["properties"]:
        if field not in last_applied_manifest:
            try:
                if field in response:
                    last_applied_manifest[field] = response[field]
                elif "default" in observer_schema["properties"][field]:
                    last_applied_manifest[field] = observer_schema["properties"][field]["default"]
            except KeyError:
                raise KeyError(f"{field} not in Kubernetes response")
        elif isinstance(last_applied_manifest[field], dict):
            last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], observer_schema["properties"][field], response
            )
        elif isinstance(last_applied_manifest[field], list):
            last_applied_manifest[field] = update_last_applied_manifest_list_from_resp(
                last_applied_manifest[field], observer_schema["properties"][field], response
            )
    return last_applied_manifest

