    if self.in_style.type == 'named':
        assert isinstance(params, Mapping)
        new_params = {}
        for key in params.keys():
            if isinstance(key, (str, int)):
                new_params[f"{self.out_style.prefix}{key}{self.out_style.suffix}"] = params[key]
            else:
                raise ValueError(f"Invalid key '{key}' in params.")
        return (sql.format(**new_params), new_params)

    elif self.in_style.type == 'ordinal':
        assert isinstance(params, Sequence)
        new_params = []
        for i, value in enumerate(params):
            new_params.append(f"{self.out_style.prefix}{i}{self.out_style.suffix}")
        return (sql.format(*new_params[1:]), new_params)

