def format(self, sql, params):
    if self.in_style == 'named':
        out_params = {}
        for name, value in dict.items(params):
            out_params[name] = value
            sql = re.sub(fr'{name}', f'?', sql)
    elif self.in_style == 'ordinal':
        out_params = []
        for ordinal, value in enumerate(params):
            out_params.append(value)
            sql = sql.replace(str(ordinal + 1), '?')
    return (sql, out_params)
