def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not self.pyfs:
        raise ValueError("OCFL object must be initialized with a pyfs root element")

    root = self.pyfs.resolve(path) if path else self.pyfs.root

    if not root.exists:
        raise ValueError(f"OCFL object at {path or 'pyfs root'} does not exist")

    if not root.isdir():
        raise ValueError(f"OCFL object at {path or 'pyfs root'} is not a directory")

    # Check for required files
    required_files = [root.resolve('storage.ocfl.json'),
                      root.resolve('spec.json'),
                      root.resolve('version.txt'),
                      root.resolve('reference.txt')]
    for file in required_files:
        if not file.exists:
            raise ValueError(f"Required file {file} not found in OCFL object at {path or 'pyfs root'}")

    # Check for valid files
    for file in root.descendants(True):
        if file == root or not file.isfile():
            continue
        if file.basename() not in valid_files:
            raise ValueError(f"Invalid file {file} found in OCFL object at {path or 'pyfs root'}")

    # Verify the presence of metadata files
    for file in required_metadata_files:
        if not root.resolve(file).exists:
            raise ValueError(f"Missing required metadata file {file} in OCFL object at {path or 'pyfs root'}")

    # Verify the presence of annotation files
    for file in required_annotation_files:
        if not root.resolve(file).exists:
            raise ValueError(f"Missing required annotation file {file} in OCFL object at {path or 'pyfs root'}")

    # Verify the presence of structmap files
    for file in required_structmap_files:
        if not root.resolve(file).exists:
            raise ValueError(f"Missing structmap file {file} in OCFL object at {path or 'pyfs root'}")

    # Verify the metadata files
    for file in required_metadata_files:
        with root.resolve(file).open() as f:
            verify_ocfl_json(f)

    # Verify the annotation files
    for file in required_annotation_files:
        with root.resolve(file).open() as f:
            verify_ocfl_json(f)

    # Verify the structmap files
    for file in required_structmap_files:
        with root.resolve(file).open() as f:
            verify_ocfl_json(f)

    return True

