        except json.JSONDecodeError:
            raise RuntimeError("Invalid inventory.json file")
        if not isinstance(inventory, list):
            raise RuntimeError("inventory.json must contain an array")

        for item in inventory:
            if not isinstance(item, dict) or "id" not in item or "sha512" not in item:
                raise RuntimeError("Invalid item in inventory.json")

        # Check that about.json is valid
        try:
            about = json.load(open(os.path.join(path, "about.json")))
        except json.JSONDecodeError:
