        if not isinstance(about, dict) or "title" not in about or "description" not in about:
            raise RuntimeError("Invalid about.json file")

        # Check that manifest.json is valid
        try:
            manifest = json.load(open(os.path.join(path, "manifest.json")))
        except json.JSONDecodeError:
            raise RuntimeError("Invalid manifest.json file")
        if not isinstance(manifest, dict) or "objects" not in manifest or "external_objects" not in manifest:
