def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # Check if path is absolute
    if not os.path.isabs(path):
        raise ValueError("Path must be absolute: " + path)

    # Get the manifest file
    manifest_path = os.path.join(path, "manifest.json")
    with open(manifest_path) as f:
        manifest = json.load(f)

    # Validate the manifest
    if not isinstance(manifest, dict):
        raise ValueError("Manifest must be a JSON object: " + str(manifest))

    # Validate the version property
    if "version" not in manifest:
        raise ValueError("Manifest must have a version property: " + str(manifest))
    if not isinstance(manifest["version"], str):
        raise ValueError("Version must be a string: " + str(manifest["version"]))

    # Validate the root property
    if "root" not in manifest:
        raise ValueError("Manifest must have a root property: " + str(manifest))
    if not isinstance(manifest["root"], dict):
        raise ValueError("Root must be a JSON object: " + str(manifest["root"]))

    # Validate the object properties
    for key in manifest["root"]:
        value = manifest["root"][key]
        if key not in self.object_properties:
            raise ValueError("Invalid object property: " + key)
        if not isinstance(value, dict):
            raise ValueError("Value must be a JSON object: " + str(value))
        for property_key in value:
            property_value = value[property_key]
            if property_key not in self.object_properties[key]:
                raise ValueError("Invalid object property key: " + property_key)
            if not isinstance(property_value, str):
                raise ValueError("Value must be a string: " + str(property_value))

    # Validate the files property
    if "files" not in manifest:
        raise ValueError("Manifest must have a files property: " + str(manifest))
    if not isinstance(manifest["files"], list):
        raise ValueError("Files must be a list: " + str(manifest["files"]))

    # Validate each file
    for file in manifest["files"]:
        if not isinstance(file, dict):
            raise ValueError("File must be a JSON object: " + str(file))

        # Validate the path property
        if "path" not in file:
            raise ValueError("File must have a path property: " + str(file))
        if not isinstance(file["path"], str):
            raise ValueError("Path must be a string: " + str(file["path"]))

        # Validate the url property
        if "url" not in file:
            raise ValueError("File must have a url property: " + str(file))
        if not isinstance(file["url"], str):
            raise ValueError("Url must be a string: " + str(file["url"]))

        # Validate the digests property
        if "digests" not in file:
            raise ValueError("File must have a digests property: " + str(file))
        if not isinstance(file["digests"], dict):
            raise ValueError("Digests must be a JSON object: " + str(file["digests"]))
        for digest_type in file["digests"]:
            if digest_type not in self.supported_digest_types:
                raise ValueError("Unsupported digest type: " + digest_type)
            if not isinstance(file["digests"][digest_type], str):
                raise ValueError("Digest value must be a string: " + str(file["digests"][digest_type]))

    return True

