def _extract_number_and_supplment_from_issue_element(issue):
    number = None
    suppl = None
    m = re.search(r'(?:\b((?:\d+|X{1,3}|[IVX]+)(?:\.\d*)?) )?(?:suppl.*((\d+|\d+\D?\d*))|\.((\d+|\d+\D?\d*))|\s*suppl\s*(\d+|\d+\D?\d*))', issue)
    if m:
        number = m.group(1)
        suppl = m.group(2)
        if not suppl:
            suppl = m.group(4)
        if not suppl:
            suppl = m.group(5)
        if not suppl:
            suppl = m.group(6)
    return number, suppl
