def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
        """Call the given command(s)."""

        if isinstance(commands, str):
            commands = [commands]

        if not isinstance(args, list):
            args = [args]

        if cwd is not None and not isinstance(cwd, str):
            raise ValueError("`cwd` must be a string or None")

        if verbose is not None and not isinstance(verbose, bool):
            raise ValueError("`verbose` must be a boolean or None")

        if hide_stderr is not None and not isinstance(hide_stderr, bool):
            raise ValueError("`hide_stderr` must be a boolean or None")

        if env is not None and not isinstance(env, dict):
            raise ValueError("`env` must be a dict or None")

        # Build the command string
        cmd = [command for command in commands for arg in args]

        # Run the command and capture the output and errors
        process = subprocess.run(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, encoding="UTF-8", universal_newlines=True)

        # Verbose mode
        if verbose:
            print(process.stdout)

        # Hide error output
        if hide_stderr:
            stdout = process.stdout.replace(process.stderr, "")
        else:
            stdout = process.stdout

        # Return the output and exit code
        return stdout, process.returncode

