def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool): Validate objects in the hierarchy
        check_digests (bool): Check object digests in the hierarchy
        show_warnings (bool): Show warnings during validation

    Returns:
        num_objects (int): Number of objects checked
        good_objects (int): Number of objects checked that were found to be valid
    """
    def check_digest(obj):
        return obj.digest is not None and obj.digest in obj.to_JSON()

    def validate_object(obj):
        if check_digests:
            if not check_digest(obj):
                return False
        if validate_objects:
            if not obj.validate():
                return False
        return True

    def traverse_hierarchy(parent):
        for child in parent.children:
            check_child = validate_object(child)
            if check_child:
                good_objects += 1
            num_objects += 1
            traverse_hierarchy(child)

    num_objects = 0
    good_objects = 0
    if show_warnings:
        warnings.warn("Validating storage root hierarchy...", RuntimeWarning)
    traverse_hierarchy(self)
    if show_warnings:
        warnings.warn(f"Finished validating storage root hierarchy. {good_objects} of {num_objects} objects were found to be valid.", RuntimeWarning)
    return num_objects, good_objects

