def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Arguments:
            validate_objects (bool): Validate objects in the hierarchy (default: True)
            check_digests (bool): Check digests (default: True)
            show_warnings (bool): Show warnings (default: False)

        Returns:
            num_objects (int): Number of objects checked
            good_objects (int): Number of objects checked that were found to be valid
        """

        num_objects = 0
        good_objects = 0
        for obj in self.objects():
            num_objects += 1
            if validate_objects and not obj.validate():
                if show_warnings:
                    warnings.warn(f"Object {obj.id} is not valid.")
            else:
                good_objects += 1

        for layer in self.layers():
            for annotation in layer.annotations():
                if check_digests and not annotation.check_digest():
                    if show_warnings:
                        warnings.warn(f"Annotation {annotation.id} has invalid digest.")
                else:
