def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import magic

    if not os.path.exists(path):
        return "Not found"

    if os.path.isfile(path):
        # Check file type
        filetype = magic.from_file(path, mime=True)
        if filetype == "text/plain":
            # Look for OCFL Storage Root files by checking for the presence of a "namaste" file
            if os.path.exists(os.path.join(path, "ocfl_object_type")):
                return "root"
    elif os.path.isdir(path):
        # Check for OCFL Directories
        if os.path.exists(os.path.join(path, "namaste")):
            return "object"
        # Check for files
        for root, _, files in os.walk(path):
            for file in files:
                filetype = magic.from_file(os.path.join(root, file), mime=True)
                if filetype == "text/plain":
                    # Look for OCFL Storage Root files by checking for the presence of a "namaste" file
                    if os.path.exists(os.path.join(root, file, "ocfl_object_type")):
                        return "root"
                    # Check for OCFL Inventory files by checking for the presence of a "ocfl.properties" file
                    if os.path.exists(os.path.join(root, file, "ocfl.properties")):
                        return "object"
    else:
        return "Unknown"
