    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser(description='Process command-line arguments')
    subparser_actived = {
        "global": True,
    }
    o = {
        "global": None,
    }
    for unparsed_argument in unparsed_arguments:
        if unparsed_argument.startswith("-"):
            # Expected argument of subparser
            subparser_name = unparsed_argument[1:]
            if subparser_name in subparser_actived:
                # Another subparser has already been activated
                return o[subparser_name]
            subparser = parser.add_subparsers(dest="subparser_name")
            subparser_actived[subparser_name] = True
            o[subparser_name] = argparse.Namespace()
        else:
            # Expected keyword arguments for the current subparser
            keyword_arguments = unparsed_argument.split("=")
            if len(keyword_arguments) == 2:
                key, value = keyword_arguments
                setattr(o[subparser_name], key, value)
            else:
                print(f"Ignoring unexpected argument {unparsed_argument}")
    return parser.parse_args(unparsed_arguments)

