# This method is written as a generator,
# as it is much faster and more efficient
# than a naive implementation of itertools.count
def count(self, cls=None, set=None, depth=True, whitelist=[]):
    """Count the number of elements of a given class and set.

    If cls is given, only count instances of that class.
    If set is given, only count elements in that set.
    If depth is True, recursively count all children as well.
    If whitelist is provided, do not count instances of any class in it.
    """
    count = 0
    for e in self:
        if isinstance(e, AbstractElement) and not any(isinstance(e, w) for w in whitelist):
            if (cls is None) or isinstance(e, cls):
                if (set is None) or (e._set == set):
                    if depth:
                        count += e._count(cls, set, depth, whitelist)
                    else:
                        count += 1
    return count

