        for name in field_names:
            if name in hist.names:
                point.append(make_value(getattr(bin_, name)))
            else:
                point.append(None)
        points.append(point)

    graph = Graph(points, labels=field_names)
    if scale is not None and scale is not False:
        graph.scale = scale if scale is True else hist.scale
    return graph
