    """
    Verifies that 2 given strings containing python code
    define classes with the same name, names, and
    arguments.

    Parameters:
    code1 (str): The first string containing python code
    code2 (str): The second string containing python code

    Returns:
    bool: True if the classes defined in the two strings
    are the same, False otherwise.
    """

    import ast
    try:
        tree1 = ast.parse(code1)
        tree2 = ast.parse(code2)
    except SyntaxError:
        return False

    class1 = None
    class2 = None

    for item in tree1.body:
        if type(item) is ast.ClassDef:
            class1 = item

    for item in tree2.body:
        if type(item) is ast.ClassDef:
            class2 = item

    if class1 is None or class2 is None:
        return False

    return class1.name == class2.name and class1.argnames == class2.argnames

