def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    if document.startswith("<?xml"):
        # Parse XRD (old) format
        parser = etree.XMLParser(recover=True)
        tree = etree.fromstring(document, parser)
        root = tree.getroot()
        nsmap = root.nsmap
        webfinger = root.find("{%s}Diaspora" % (nsmap["ds"]))
        if webfinger is None:
            raise ValueError("Invalid webfinger document")
        webfinger_dict = {}
        for child in webfinger.getchildren():
            tag = child.tag.split("}")[-1]
            webfinger_dict[tag] = child.text
        return webfinger_dict
    else:
        # Parse JSON (new) format
        return json.loads(document)

