import requests
import xml.etree.ElementTree as ET

def retrieve_and_parse_diaspora_webfinger(handle):
    url = f"https://{handle}/webfinger.xml"
    response = requests.get(url)
    if response.status_code != 200:
        raise Exception("Failed to retrieve webfinger document")
    root = ET.fromstring(response.text)
    return parse_diaspora_webfinger(root)

def parse_diaspora_webfinger(root):
    webfinger = {}
    for child in root:
        if child.tag == "Identity":
            identity = parse_identity(child)
            webfinger["identity"] = identity
        elif child.tag == "Alias":
            alias = parse_alias(child)
            webfinger["aliases"] = alias
    return webfinger

def parse_identity(identity):
    id = identity.get("id")
    href = identity.get("href")
    properties = get_properties(identity)
    return {"id": id, "href": href, "properties": properties}

def parse_alias(alias):
    id = alias.get("id")
    href = alias.get("href")
    properties = get_properties(alias)
    return {"id": id, "href": href, "properties": properties}

def get_properties(element):
    properties = {}
    for child in element:
        if child.tag == "Property":
            name = child.get("name")
            value = child.get("value")
            if name and value:
                properties[name] = value
    return properties
